9904],[42.44846,0.349804],[42.448544,0.349675],[42.448682,0.349413],[42.448818,0.349098],[42.449035,0.34866],[42.449162,0.348448],[42.449274,0.348348],[42.4494,0.348225],[42.449491,0.348094],[42.44956,0.347974],[42.449616,0.347824],[42.449708,0.347649],[42.449739,0.347548],[42.449754,0.347419],[42.449798,0.347292],[42.449896,0.34713],[42.449957,0.346992],[42.450054,0.346731],[42.450132,0.346593],[42.450205,0.346504],[42.450255,0.346444],[42.450348,0.346409],[42.450444,0.346399],[42.450514,0.346376],[42.45055,0.346288],[42.450586,0.346116],[42.450657,0.346019],[42.450742,0.346012],[42.450809,0.346011],[42.450874,0.345947],[42.450932,0.34584],[42.451032,0.345692],[42.451185,0.345489],[42.451279,0.34538],[42.451395,0.345284],[42.451494,0.345204],[42.451676,0.345072],[42.451753,0.345024],[42.451811,0.345012],[42.451875,0.34505],[42.45193,0.345156],[42.451972,0.345215],[42.45203,0.345275],[42.452146,0.345361],[42.452225,0.345389],[42.452304,0.345388],[42.452365,0.345367],[42.452422,0.345303],[42.452474,0.345208],[42.45251,0.34513],[42.452542,0.345035],[42.452571,0.344925],[42.452622,0.344707],[42.452663,0.344522],[42.452677,0.344394],[42.452698,0.344316],[42.452736,0.344243],[42.452847,0.344115],[42.452893,0.344038],[42.452918,0.343961],[42.452934,0.343885],[42.452967,0.343829],[42.453079,0.343717],[42.453133,0.343635],[42.453176,0.343578],[42.453243,0.343534],[42.453357,0.343508],[42.453417,0.343483],[42.453485,0.343435],[42.453585,0.343349],[42.453667,0.343256],[42.453758,0.343144],[42.453809,0.343057],[42.453851,0.342969],[42.453881,0.342896],[42.453905,0.342815],[42.453915,0.342728],[42.453914,0.342623],[42.453935,0.342541],[42.454036,0.342588],[42.454106,0.342724],[42.454116,0.342836],[42.454119,0.343005],[42.454125,0.343238],[42.454134,0.343322],[42.45417,0.343415],[42.45425,0.343506],[42.454376,0.343609],[42.454481,0.343714]]$coords$::jsonb;
  v_landmarks jsonb := $landmarks$[[42.454481,0.343714],[42.44186,0.351256],[42.434005,0.36561],[42.434011,0.365656]]$landmarks$::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
  v_closing_gap_m double precision;
  v_landmark_gap_m double precision;
begin
  select jsonb_agg(jsonb_build_object(
    'lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision
  ) order by ordinality)
    into v_points
    from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);
  select h.id,h.latitude,h.longitude,h.published,h.trace_available,
      h.official_url,h.description,h.distance_km,h.route_type,
      h.duration_minutes,h.ascent_m,
      t.status,t.segments,t.geometry_source,t.geometry_source_url,
      t.official,t.continuity_checked,t.checked_at
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-9693152'
      and h.source='openstreetmap' and h.source_type='relation'
      and h.external_id=9693152
      and h.name='Campo - Viú - Senz'
      and h.route_ref='PR-HU 120' and h.raw_tags->>'ref'='PR-HU 120'
      and h.source_url='https://www.openstreetmap.org/relation/9693152'
      and (h.official_url is not distinct from null
        or h.official_url='https://turismoribagorza.org/ruta/pr-hu-120-presa-del-embalse-de-argone-senz-ermita-de-san-roque-viu/')
      and h.region_code='huesca' and h.province='Huesca'
      and h.latitude=42.4406466 and h.longitude=0.3639927
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.region_code='huesca' and r.published)
    for update of h,t;
  if not found then
    raise exception 'PR-HU 120 route identity or published region changed';
  end if;
  if v_route.status='ready' then
    if v_route.geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/45_pr_hu_120.gpx'
      and v_route.geometry_source='Comarca de Ribagorza - GPX oficial PR-HU 120'
      and v_route.segments=jsonb_build_array(v_points)
      and v_route.official and v_route.continuity_checked
      and v_route.checked_at is not null
      and v_route.published and v_route.trace_available
      and v_route.official_url='https://turismoribagorza.org/ruta/pr-hu-120-presa-del-embalse-de-argone-senz-ermita-de-san-roque-viu/'
      and v_route.distance_km=10.32
      and v_route.route_type='Lineal'
      and v_route.duration_minutes is null
      and v_route.ascent_m is null
      and v_route.description='PR-HU 120 desde la presa del embalse de Argoné hasta Viú, con visitas a Senz y la ermita de San Roque y regreso a los cruces de la ruta principal. El GPX oficial contiene la ida: 10,32 km. La ficha incluye el regreso a la presa y advierte de tramos con vegetación cerrada y señalización deteriorada.' then
      return;
    end if;
    raise exception 'PR-HU 120 route has another ready trace or publication state';
  end if;
  if v_route.status is distinct from 'missing'
    or v_route.published is distinct from false
    or v_route.trace_available is distinct from false
    or v_route.segments is not null or v_route.geometry_source_url is not null
    or v_route.geometry_source is distinct from 'OpenStreetMap'
    or v_route.official is distinct from false
    or v_route.continuity_checked is distinct from true
    or v_route.official_url is distinct from null
    or v_route.description is distinct from 'Campo - Viú - Senz'
    or v_route.distance_km is distinct from 10
    or v_route.ascent_m is not null or v_route.duration_minutes is not null
    or v_route.route_type is distinct from null then
    raise exception 'PR-HU 120 hidden route state changed';
  end if;
  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
      (lat between 42.42 and 42.46 and lon between 0.34 and 0.39) valid
    from steps
  )
  select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
    coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;
  select ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint(0.3855,42.426865)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision),
    ST_MakePoint(0.343714,42.454481)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision))
    into v_start_gap_m,v_end_gap_m,v_closing_gap_m;
  select max(nearest.gap_m) into v_landmark_gap_m
    from jsonb_array_elements(v_landmarks) as w(landmark)
    cross join lateral (
      select min(ST_DistanceSphere(
        ST_MakePoint((point->>1)::double precision,(point->>0)::double precision),
        ST_MakePoint((w.landmark->>1)::double precision,(w.landmark->>0)::double precision))) gap_m
      from jsonb_array_elements(v_coords) as p(point)
    ) nearest;
  if v_count<>859 or v_invalid>0
    or abs(v_length_km-10.317391)>0.015
    or v_max_gap_km>0.046 or v_center_gap_km>0.22
    or v_start_gap_m>2 or v_end_gap_m>2 or v_closing_gap_m<500
    or v_landmark_gap_m>10 then
    raise exception 'PR-HU 120 GPS validation failed: points %, length %, gap %, center %, start %, end %, closure %, landmarks %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,
      v_start_gap_m,v_end_gap_m,v_closing_gap_m,v_landmark_gap_m,v_invalid;
  end if;
  update public.hiking_route_tracks
    set status='ready',segments=jsonb_build_array(v_points),checked_at=now(),
      continuity_checked=true,geometry_source='Comarca de Ribagorza - GPX oficial PR-HU 120',
      geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/45_pr_hu_120.gpx',official=true
    where route_id=v_route.id and status='missing';
  if not found then
    raise exception 'PR-HU 120 track state changed';
  end if;
  update public.hiking_routes
    set trace_available=true,published=true,
      distance_km=round(v_length_km::numeric,2),route_type='Lineal',
      official_url='https://turismoribagorza.org/ruta/pr-hu-120-presa-del-embalse-de-argone-senz-ermita-de-san-roque-viu/',description='PR-HU 120 desde la presa del embalse de Argoné hasta Viú, con visitas a Senz y la ermita de San Roque y regreso a los cruces de la ruta principal. El GPX oficial contiene la ida: 10,32 km. La ficha incluye el regreso a la presa y advierte de tramos con vegetación cerrada y señalización deteriorada.'
    where id=v_route.id and not published and not trace_available;
  if not found then
    raise exception 'PR-HU 120 publication state changed';
  end if;
end
